import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiImage } from 'react-icons/fi';
import eventService from '../services/eventService';
import EventCard from '../components/EventCard';
import '../styles/Pages.css';

const PastEvents = () => {
  const navigate = useNavigate();
  const [pastEvents, setPastEvents] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchPastEvents();
  }, []);

  const fetchPastEvents = async () => {
    setLoading(true);
    try {
      const data = await eventService.getPastEvents();
      setPastEvents(data);
    } catch (error) {
      console.error('Error fetching past events:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleViewDetails = (eventId) => {
    navigate(`/past-events/${eventId}`);
  };

  return (
    <div className="past-events-page">
      <div className="page-header">
        <div className="header-content">
          <div>
            <h1>Past Events</h1>
            <p>Relive amazing event memories</p>
          </div>
          <button 
            className="btn-manage-events"
            onClick={() => navigate('/manage-past-events')}
          >
            <FiImage size={20} />
            Manage Events
          </button>
        </div>
      </div>

      {loading ? (
        <div className="loading">Loading past events...</div>
      ) : pastEvents.length > 0 ? (
        <div className="events-grid">
          {pastEvents.map(event => (
            <EventCard
              key={event._id}
              event={event}
              onViewDetails={handleViewDetails}
            />
          ))}
        </div>
      ) : (
        <div className="no-events">
          <p>No past events yet</p>
        </div>
      )}
    </div>
  );
};

export default PastEvents;
